import java.util.Arrays;
public class AlgorithmsTest {
 static int count=0;
 static void check(boolean value,String label){if(!value)throw new AssertionError(label);count++;}
 static int[] list(Algorithms.IntList a){return Arrays.copyOf(a.data,a.count);}
 static Algorithms.Graph graph(){Algorithms.Graph g=new Algorithms.Graph();g.nodeCount=6;for(int i=0;i<6;i++)g.nodes[i]=i;int[][] edges={{0,1,4},{0,2,2},{1,2,1},{1,3,5},{2,3,8},{2,4,10},{3,4,2},{3,5,6},{4,5,3}};g.edgeCount=edges.length;for(int i=0;i<edges.length;i++){Algorithms.Edge e=new Algorithms.Edge();e.from=edges[i][0];e.to=edges[i][1];e.weight=edges[i][2];g.edges[i]=e;}return g;}
 static int validate(Algorithms.Node n,int low,int high,boolean avl){if(n==null)return 1;check(n.value>low&&n.value<high,"tree order");int left=validate(n.left,low,n.value,avl),right=validate(n.right,n.value,high,avl);if(avl){check(Math.abs(left-right)<=1,"AVL balance");return Math.max(left,right)+1;}check(left==right,"black height");check(n.right==null||!n.right.red,"left-leaning red");check(!n.red||n.left==null||!n.left.red,"red/red");return left+(n.red?0:1);}
 public static void main(String[] args){
  for(int[] a:new int[][]{{},{1},{3,2,1},{7,7,2},{-4,1,0}}){int n=a.length;int[] expected=a.clone();Arrays.sort(expected);
   check(Arrays.equals(list(Algorithms.bubbleSort(a,n)),expected),"bubble");check(Arrays.equals(list(Algorithms.selectionSort(a,n)),expected),"selection");check(Arrays.equals(list(Algorithms.insertionSort(a,n)),expected),"insertion");check(Arrays.equals(list(Algorithms.mergeSort(a,n)),expected),"merge");check(Arrays.equals(list(Algorithms.quickSort(a,n)),expected),"quick");if(Arrays.stream(a).allMatch(x->x>=0))check(Arrays.equals(list(Algorithms.radixSort(a,n)),expected),"radix");
   check(Arrays.equals(list(Algorithms.queueDemo(a,n)),a),"queue");check(Arrays.equals(list(Algorithms.priorityQueueDemo(a,n)),expected),"priority");Algorithms.IntList heap=Algorithms.buildMinHeap(a,n);for(int i=1;i<n;i++)check(heap.data[(i-1)/2]<=heap.data[i],"heap");
   int[] reversed=a.clone();for(int i=0;i<n;i++)reversed[i]=a[n-i-1];check(Arrays.equals(list(Algorithms.stackDemo(a,n)),reversed),"stack");
   for(Algorithms.Link head:new Algorithms.Link[]{Algorithms.buildSinglyLinkedList(a,n),Algorithms.buildDoublyLinkedList(a,n),Algorithms.buildCircularList(a,n)}){Algorithms.Link node=head;for(int value:a){check(node.value==value,"link values");node=node.next;}}
   int target=n>0?a[0]:99;check(Algorithms.hashMapChaining(a,n,target).found==(n>0),"chaining");check(Algorithms.hashMapProbing(a,n,target).found==(n>0),"probing");check(Algorithms.hashSet(a,n,target).found==(n>0),"set");
  }
  for(int seed=1;seed<=40;seed++){int[] a=new int[20];for(int i=0;i<20;i++)a[i]=(i*seed*13+seed*7)%97;validate(Algorithms.buildAVLTree(a,a.length),Integer.MIN_VALUE,Integer.MAX_VALUE,true);Algorithms.Node rb=Algorithms.buildRedBlackTree(a,a.length);validate(rb,Integer.MIN_VALUE,Integer.MAX_VALUE,false);check(!rb.red,"black root");}
  check(Algorithms.linearSearch(new int[]{1,3},2,3)==1,"linear");check(Algorithms.binarySearch(new int[]{9,2,3},3,3)==1,"binary");check(Algorithms.traverseArray(new int[]{1,2,3},3)==6,"sum");check(Algorithms.maxWindowSum(new int[]{1,2,3,4},4,2)==7,"window");check(Algorithms.findPairSum(new int[]{1,8,3},3,9).count==2,"pair");int[] text="a🙂b".codePoints().toArray();Algorithms.reverseCodepoints(text,text.length);check(new String(text,0,text.length).equals("b🙂a"),"Unicode");check(Arrays.equals(list(Algorithms.dequeDemo(new int[]{1,2,3,4},4)),new int[]{3,4,1,2}),"deque");
  check(Algorithms.buildAndSearchBST(new int[]{3,1,4},3,1).value==3,"bst");check(Arrays.equals(list(Algorithms.treeBreadthFirst(new int[]{3,1,4,2},4)),new int[]{3,1,4,2}),"tree bfs");check(Arrays.equals(list(Algorithms.treeDepthFirst(new int[]{3,1,4,2},4)),new int[]{3,1,2,4}),"tree dfs");
  Algorithms.Graph g=graph();check(Arrays.equals(list(Algorithms.graphBreadthFirst(g,0)),new int[]{0,1,2,3,4,5}),"graph bfs");check(Algorithms.graphDepthFirst(g,0).count==6,"graph dfs");check(Arrays.equals(Arrays.copyOf(Algorithms.shortestDistances(g,0).data,6),new double[]{0,3,2,8,10,13}),"dijkstra");
  Algorithms.Graph dag=new Algorithms.Graph();dag.nodeCount=3;for(int i=0;i<3;i++)dag.nodes[i]=i;dag.edgeCount=2;for(int i=0;i<2;i++){Algorithms.Edge e=new Algorithms.Edge();e.from=i;e.to=i+1;e.weight=1;dag.edges[i]=e;}check(Arrays.equals(list(Algorithms.topologicalSort(dag)),new int[]{0,1,2}),"topological");Algorithms.Edge cycle=new Algorithms.Edge();cycle.from=2;cycle.to=0;cycle.weight=1;dag.edges[2]=cycle;dag.edgeCount=3;check(Algorithms.topologicalSort(dag).count==-1,"cycle");
  for(int n=0;n<=20;n++){int a=0,b=1;for(int i=0;i<n;i++){int temp=a+b;a=b;b=temp;}check(Algorithms.fibonacciTable(n)==a,"table");check(Algorithms.fibonacciMemo(n)==a,"memo");}check(Algorithms.knapsack(new int[]{6,10,12},3,5)==22,"knapsack");
  System.out.println(count+" Java execution checks passed across all 35 lessons");
 }
}
